def _get_projection(self):
    """Get projection from the NetCDF4 attributes."""
    try:
        proj_str = self.nc.attrs["gdal_projection"]
    except TypeError:
        proj_str = self.nc.attrs["gdal_projection"].decode()

    xgeo_multiplier = 1.0
    if "+h=1.000000" in proj_str:
        h_actual = self.nc.attrs.get("perspective_point_height")
        if h_actual is None:
            try:
                with xr.open_dataset(self.filename, group="projection_definition") as ds_proj:
                    h_actual = ds_proj.attrs.get("perspective_point_height")
            except Exception:
                pass

        if h_actual is not None:
            proj_str = proj_str.replace("+h=1.000000", f"+h={h_actual}")
            xgeo_multiplier = h_actual

    # Check the a/b/h units
    radius_a = proj_str.split("+a=")[-1].split()[0]
    if float(radius_a) > 10e3:
        units = "m"
        scale = 1.0
    else:
        units = "km"
        scale = 1e3

    if "units" not in proj_str:
        proj_str = proj_str + " +units=" + units

    area_extent = (float(self.nc.attrs["gdal_xgeo_up_left"]) * xgeo_multiplier / scale,
                   float(self.nc.attrs["gdal_ygeo_low_right"]) * xgeo_multiplier / scale,
                   float(self.nc.attrs["gdal_xgeo_low_right"]) * xgeo_multiplier / scale,
                   float(self.nc.attrs["gdal_ygeo_up_left"]) * xgeo_multiplier / scale)

    crs = CRS.from_string(proj_str)
    return crs, area_extent
